class ApiError extends Error { constructor(public status: number, message: string) { super(message) } }
function apiErrorMessage(detail: unknown, fallback: string) {
  if (typeof detail === 'string') return detail
  if (Array.isArray(detail)) return detail.map((item:any) => {
    const where=Array.isArray(item?.loc)?item.loc.filter((part:any)=>part!=='body').join(' → '):''
    return [where,item?.msg].filter(Boolean).join(': ')
  }).filter(Boolean).join('; ') || fallback
  if (detail && typeof detail === 'object') {
    const value=detail as Record<string,unknown>
    return typeof value.message==='string'?value.message:typeof value.msg==='string'?value.msg:fallback
  }
  return fallback
}
function cookie(name: string) { return document.cookie.split('; ').find(value => value.startsWith(`${name}=`))?.slice(name.length + 1) || '' }
async function request(path: string, init?: RequestInit) {
  const method = (init?.method || 'GET').toUpperCase()
  const csrf = !['GET', 'HEAD', 'OPTIONS'].includes(method) ? cookie('apisentinel_csrf') : ''
  const headers = new Headers(init?.headers)
  if (!headers.has('Content-Type') && !(init?.body instanceof FormData)) headers.set('Content-Type', 'application/json')
  if (csrf && path !== '/auth/login') headers.set('X-CSRF-Token', decodeURIComponent(csrf))
  let res: Response
  try { res = await fetch(`${API}${path}`, { ...init, credentials: 'include', headers }) }
  catch { throw new Error('APISentinel API is unavailable. Start the API service and try again.') }
  if (!res.ok) { const err = await res.json().catch(() => ({})); throw new ApiError(res.status, apiErrorMessage(err.detail, `Request failed (${res.status})`)) }
  return res.json()
}
async function requestPage(path: string) {
  let res: Response
  try { res = await fetch(`${API}${path}`, { credentials: 'include', headers: { Accept: 'application/json' } }) }
  catch { throw new Error('APISentinel API is unavailable. Start the API service and try again.') }
  if (!res.ok) { const err = await res.json().catch(() => ({})); throw new ApiError(res.status, apiErrorMessage(err.detail, `Request failed (${res.status})`)) }
  return { rows: await res.json(), total: Number(res.headers.get('X-Total-Count') || 0) }
}
async function uploadFile(path: string, field: string, file: File) {
  const headers = new Headers()
  const csrf = cookie('apisentinel_csrf')
  if (csrf) headers.set('X-CSRF-Token', decodeURIComponent(csrf))
  const form = new FormData(); form.append(field, file)
  let res: Response
  try { res = await fetch(`${API}${path}`, { method: 'POST', credentials: 'include', headers, body: form }) }
  catch { throw new Error('APISentinel API is unavailable. Start the API service and try again.') }
  if (!res.ok) { const err = await res.json().catch(() => ({})); throw new ApiError(res.status, apiErrorMessage(err.detail, `Request failed (${res.status})`)) }
  return res.json()
}
