const countFormatter = new Intl.NumberFormat('en-US')
const formatCount = (value: number | string | null | undefined) => value !== null && value !== undefined && value !== '' && Number.isFinite(Number(value)) ? countFormatter.format(Number(value)) : '—'
const date = (value?: string, timeZone?: string) => {
  const parsed = value ? new Date(value) : null
  return parsed && Number.isFinite(parsed.getTime()) ? new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone }).format(parsed) : '—'
}
const time = (value?: string, timeZone?: string) => {
  const parsed = value ? new Date(value) : null
  return parsed && Number.isFinite(parsed.getTime()) ? new Intl.DateTimeFormat('en-US', { hour: 'numeric', minute: '2-digit', timeZone }).format(parsed) : '—'
}
const dateTime = (value?: string) => value && date(value) !== '—' ? `${date(value)} · ${time(value)}` : '—'
function MetricValue({ value }: { value: number | string }) {
  const ratio = typeof value === 'string' ? value.match(/^(\d+)\/(\d+)$/) : null
  if (ratio) return <span className="metric-ratio"><span>{formatCount(ratio[1])}</span><span className="metric-ratio-total"><i>/</i>{formatCount(ratio[2])}</span></span>
  return <>{Number.isFinite(Number(value)) ? formatCount(value) : value}</>
}
