const localDateTime = (value?: string) => { if (!value) return ''; const parsed = new Date(value); return new Date(parsed.getTime() - parsed.getTimezoneOffset() * 60000).toISOString().slice(0, 16) }
const displayState = (value: string) => (({ WEB_API: 'Web API', ANDROID_API: 'Android API', BOTH: 'Web & Android' } as Record<string, string>)[value] || value.toLowerCase().replaceAll('_',' ').replace(/\b\w/g,letter=>letter.toUpperCase()).replace(/\bApi\b/g,'API').replace(/\bHttp\b/g,'HTTP').replace(/\bCvss\b/g,'CVSS'))
function dashboardRequestPath(start='',end='') {
  const params=new URLSearchParams()
  if(start)params.set('start_at',`${start}T00:00:00Z`)
  if(end){const exclusive=new Date(`${end}T00:00:00Z`);exclusive.setUTCDate(exclusive.getUTCDate()+1);params.set('end_at',exclusive.toISOString())}
  return `/dashboard${params.size?`?${params}`:''}`
}
function useWorkspaceDialogs() {
  useEffect(()=>{
    let dialog:HTMLElement|null=null,opener:HTMLElement|null=null,previousOverflow=''
    const sync=()=>{
      const dialogs=document.querySelectorAll<HTMLElement>('[role="dialog"][aria-modal="true"]')
      const next=dialogs.item(dialogs.length-1)
      if(next===dialog)return
      if(!next){if(dialog){document.body.style.overflow=previousOverflow;if(opener?.isConnected)opener.focus()}dialog=null;return}
      if(!dialog){opener=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow}
      dialog=next;document.body.style.overflow='hidden'
      const focus=dialog.querySelector<HTMLElement>('input:not([type="hidden"]):not(:disabled),select:not(:disabled),textarea:not(:disabled),button:not(:disabled)')
      focus?.focus()
    }
    const onKey=(event:KeyboardEvent)=>{
      if(!dialog||event.defaultPrevented)return
      if(event.key==='Escape'){const close=dialog.querySelector<HTMLButtonElement>('button[aria-label^="Close"],.modal-head > button');if(close){event.preventDefault();close.click()}return}
      if(event.key!=='Tab')return
      const items=Array.from(dialog.querySelectorAll<HTMLElement>('a[href],button:not(:disabled),input:not(:disabled):not([type="hidden"]),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')).filter(item=>item.getClientRects().length>0)
      const first=items[0],last=items[items.length-1]
      if(!first){event.preventDefault();return}
      if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last.focus()}
      else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus()}
    }
    const observer=new MutationObserver(sync)
    observer.observe(document.body,{childList:true,subtree:true})
    document.addEventListener('keydown',onKey)
    sync()
    return()=>{observer.disconnect();document.removeEventListener('keydown',onKey);if(dialog)document.body.style.overflow=previousOverflow}
  },[])
}
const SELECTED_ASSESSMENT_STORAGE_KEY = 'apisentinel.selectedAssessment'
