function badgeLabel(value: React.ReactNode): string {
  if (typeof value === 'string' || typeof value === 'number') return String(value)
  if (Array.isArray(value)) return value.map(badgeLabel).join('')
  if (value && typeof value === 'object') {
    const item = value as AnyRow
    if ('props' in item) return badgeLabel(item.props?.children)
    return String(item.status ?? item.outcome ?? item.value ?? item.label ?? '')
  }
  return ''
}
const Badge = ({ children }: { children: React.ReactNode }) => {
  const label = badgeLabel(children)
  const variant = label.toLowerCase().trim().replaceAll(/[^a-z0-9]+/g, '-')
  const isPlainObject = children !== null && typeof children === 'object' && !Array.isArray(children) && !('props' in (children as AnyRow))
  const content = isPlainObject ? (label || 'Status unavailable') : typeof children==='string'&&/^[A-Z][A-Z_ ]+$/.test(label)&&!['GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS','TRACE','JSON','PDF','CSV','HTML','API','MFA'].includes(label)?displayState(label):children ?? 'Status unavailable'
  return <span className={`badge${variant ? ` ${variant}` : ''}`}>{content}</span>
}
