  <section className="card panel coverage-next-panel"><div className="panel-head coverage-next-heading"><Gauge size={21}/><div><h2>Assessment coverage</h2><p>Review your API inventory, check outcomes, and findings in one place.</p></div></div><div className="coverage-page-links"><Button kind="secondary" onClick={()=>navigate('/discovery')}>API Discovery <ArrowUpRight size={14}/></Button><Button kind="secondary" onClick={()=>navigate('/testing')}>Security Testing <ArrowUpRight size={14}/></Button><Button kind="secondary" onClick={()=>navigate('/findings')}>Findings <ArrowUpRight size={14}/></Button></div></section>
