 const [assessmentFilter,setAssessmentFilter]=useState('all')
 const scopedFindings=rows.filter((f:any)=>assessmentFilter==='all'||String(f.assessment_id)===assessmentFilter)
 const needsReviewCount=scopedFindings.filter((f:any)=>['PENDING_VALIDATION','NEEDS_REVIEW'].includes(String(f.validation_state||'').toUpperCase())).length
 const confirmedCount=scopedFindings.filter((f:any)=>String(f.status||'').toLowerCase()==='confirmed').length
 const openRemediationCount=scopedFindings.filter((f:any)=>!['VERIFIED_FIXED','CLOSED','ACCEPTED_RISK'].includes(String(f.remediation_status||'OPEN').toUpperCase())).length
 const criticalHighCount=scopedFindings.filter((f:any)=>['CRITICAL','HIGH'].includes(String(f.severity||'').toUpperCase())).length
 const [findingSearch,setFindingSearch]=useState(''),[severityFilter,setSeverityFilter]=useState('all'),[validationFilter,setValidationFilter]=useState('all'),[triageFilter,setTriageFilter]=useState('all'),[remediationFilter,setRemediationFilter]=useState('all')
 const filterState=(value:any)=>String(value||'').toUpperCase().replaceAll(' ','_')
 const viewFindings=scopedFindings
 const visibleFindings=viewFindings.filter((f:any)=>{const query=findingSearch.trim().toLowerCase(),searchable=[f.title,f.endpoint,f.vulnerability_category,f.owasp_categories?.join(' '),f.id].join(' ').toLowerCase();return(!query||searchable.includes(query))&&(severityFilter==='all'||String(f.severity||'').toLowerCase()===severityFilter)&&(validationFilter==='all'||filterState(f.validation_state)===validationFilter)&&(triageFilter==='all'||filterState(f.status)===triageFilter)&&(remediationFilter==='all'||filterState(f.remediation_status)===remediationFilter)})
