 async function saveCvss(){if(isWorkflowScenario(active))return;setError('');if(cvssReason.trim().length<10){setError('Enter a reason of at least 10 characters.');return}setRiskBusy(true);try{const updated=await request(`/findings/${active.id}/risk`,{method:'PATCH',body:JSON.stringify({cvss_vector:cvssVector.trim()||null,reason:cvssReason.trim()})});setActive(updated);setCvssVector(updated.risk_analysis?.cvss?.vector||'');setCvssReason('');setHistory(await request(`/findings/${active.id}/history`))}catch(e){setError(e instanceof Error?e.message:'CVSS update failed')}finally{setRiskBusy(false)}}
 async function uploadScreenshot(file:File|null,input:HTMLInputElement){if(!file||isWorkflowScenario(active))return;setError('');setAttachmentBusy(true);try{const body=new FormData();body.append('image',file);body.append('caption',screenshotCaption);const saved=await request(`/findings/${active.id}/evidence-attachments`,{method:'POST',body});setActive((current:any)=>current?{...current,evidence_attachments:[...(current.evidence_attachments||[]),saved]}:current);setScreenshotCaption('');input.value=''}catch(e){setError(e instanceof Error?e.message:'Screenshot upload failed')}finally{setAttachmentBusy(false)}}
