 async function validate(){if(isWorkflowScenario(active))return;setError('');if(validationReason.trim().length<10){setError('Enter validation rationale of at least 10 characters.');return}try{const next=validationTarget||'NEEDS_REVIEW';await onValidate(active.id,next,validationReason.trim());setActive((current:any)=>current?{...current,validation_state:next,validation_rationale:validationReason.trim()}:null);setValidationReason('');const latest=await request(`/findings/${active.id}/history`);setHistory(latest)}catch(e){setError(e instanceof Error?e.message:'Validation update failed')}}
